n_count=0
for r in csv.DictReader(open(VALUES_CSV)):
    sid=r['timeseries_id']
    if sid in ids:
        ts=r['timestamp']
        if ts.startswith(target_day):
            v=float(r['value'])
            if ids[sid]=='temp': temps[ts]=v
            if ids[sid]=='heat': heat[ts]=v
            if ids[sid]=='cool': cool[ts]=v
            n_count+=1
print("counts:",len(temps),len(heat),len(cool), "total",n_count)
# Sample
tks=sorted(temps)[:3]
print("temp first:",tks,[temps[k] for k in tks])
print("heat first:",tks,[heat.get(k) for k in tks])
print("cool first:",tks,[cool.get(k) for k in tks])
# Check
violations=[]
for ts in sorted(temps):
    if ts not in heat or ts not in cool:
        violations.append((ts,'missing','n/a'))
        continue
    t,h,c=temps[ts],heat[ts],cool[ts]
    if not (h <= t <= c):
        violations.append((ts,t,h,c))
